let state='intro',lane=1,x=0,y=0,vy=0,jumps=0,distance=0,score=0,coins=0,health=3,energy=100,combo=1,tricks=0,airPoints=0,airTricks=new Set(),invincible=0,flip=0,spin=0,boostHeld=false,time=0,notice=0,best=0,sound=false,audio=null,landings=0,completed=new Set();try{best=Number(localStorage.getItem('raccoon-best')||0);}catch{}$('best').textContent=String(best).padStart(5,'0');
function beep(freq=440,duration=.08,type='sine',gain=.03){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();let o=audio.createOscillator(),v=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.65,audio.currentTime+duration);v.gain.setValueAtTime(gain,audio.currentTime);v.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(v);v.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch{}}
function toast(text){$('trick').textContent=text;$('trick').classList.add('show');notice=2;}
function jump(){if(state!=='playing'||jumps>=2)return;vy=jumps===0?9.4:8.2;jumps++;if(jumps===1){airPoints=25;airTricks.clear();}beep(480,.12);}
function trick(kind){if(state!=='playing'||y<.4||airTricks.has(kind))return;airTricks.add(kind);airPoints+=kind==='flip'?150:200;tricks++;if(kind==='flip')flip=1;else spin=1;toast(kind==='flip'?'KICKFLIP · 翻板 +150':'360° · 月下转体 +200');beep(kind==='flip'?700:900,.14,'triangle');}
function act(a){if(state!=='playing')return;if(a==='left')lane=Math.max(0,lane-1);if(a==='right')lane=Math.min(2,lane+1);if(a==='jump')jump();if(a==='flip')trick('flip');if(a==='spin')trick('spin');}
function visible(id,on){$(id).classList.toggle('hidden',!on);}function reset(){lane=1;x=0;y=0;vy=0;jumps=0;distance=0;score=0;coins=0;health=3;energy=100;combo=1;tricks=0;airPoints=0;invincible=0;flip=0;spin=0;boostHeld=false;completed.clear();for(let item of items){item.taken=false;item.mesh.visible=true;}for(let ob of obstacles)ob.hit=false;for(let r of ramps)r.used=false;for(let g of chunks)g.visible=true;state='playing';document.body.classList.add('playing');visible('intro',false);visible('sceneNote',false);visible('overlay',false);visible('hud',true);visible('mission',true);visible('hint',true);visible('touch',matchMedia('(pointer:coarse)').matches||innerWidth<760);$('pause').textContent='Ⅱ';toast('夜滑开始 · 跟着金色拉面走');}
function showModal(title,html,button,action){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('resume').textContent=button;$('resume').onclick=action;visible('overlay',true);}
function togglePause(){if(state==='playing'){state='paused';boostHeld=false;$('pause').textContent='▶';showModal('让夜风等一会儿',`<p>你的滑板已停稳。准备好后，继续穿越夜市。</p><p>空格跳跃，可再按一次二段跳。腾空时按 J 翻板、K 转体，落地即可兑现连击。</p>`,'继续夜滑',()=>{state='playing';visible('overlay',false);$('pause').textContent='Ⅱ';});}else if(state==='paused'){state='playing';visible('overlay',false);$('pause').textContent='Ⅱ';}}
function end(){state='over';boostHeld=false;let total=Math.floor(score+distance*2);score=total;let record=total>best;if(record){best=total;try{localStorage.setItem('raccoon-best',best);}catch{}}showModal(record?'新的夜市传说！':'今夜，尽兴而归',`<p>${record?'你刷新了这台设备上的最高纪录。':'阿栗抱着滑板，准备再来一趟。'}</p><div class="result"><div><strong>${total}</strong><span>总得分</span></div><div><strong>${Math.floor(distance)}m</strong><span>滑行距离</span></div><div><strong>${coins}</strong><span>拉面收集</span></div></div><p>完成特技 ${tricks} 次 · 夜行清单 ${completed.size}/3<br>个人最佳 ${best} 分</p>`,'再滑一局',reset);beep(180,.4,'triangle');}
function hit(fall=false){if(invincible>0)return;health--;combo=1;airPoints=0;invincible=2.3;toast(fall?'险些掉下屋顶！ −1 ♥':'撞到了！ −1 ♥');beep(110,.22,'sawtooth',.04);if(health<=0){end();return;}if(fall){distance=Math.ceil((distance+18)/36)*36-16;y=2.7;vy=0;jumps=1;}else{y=.3;vy=6;jumps=1;}}
$('start').onclick=reset;$('help').onclick=()=>showModal('夜滑指南',`<p>← → 或 A / D 在三条屋顶路线间切换。</p><p>空格：跳跃，空中再按可二段跳。<br>J：翻板；K：360° 转体。每次腾空各可使用一次，安全落地增加连击倍率。</p><p>Shift：消耗能量冲刺。收集拉面补充能量。<br>金色斜坡会自动起跳；手动跳跃也能跨越楼间缝隙。避开木箱与空调，保住 3 颗爱心。</p><p>移动端使用屏幕按钮。完成三项夜行清单，每项奖励 500 分。</p>`,'明白，出发',reset);$('pause').onclick=togglePause;$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'声音 ON':'声音 OFF';$('sound').setAttribute('aria-label',sound?'关闭音效':'打开音效');beep(660);};
window.addEventListener('keydown',e=>{if(['Space','ArrowLeft','ArrowRight','ArrowUp','ShiftLeft','ShiftRight','Escape','KeyA','KeyD','KeyJ','KeyK'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Escape'){togglePause();return;}if(state==='intro'&&e.code==='Space'){reset();return;}if(e.code==='ShiftLeft'||e.code==='ShiftRight')boostHeld=true;act({ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',Space:'jump',ArrowUp:'jump',KeyJ:'flip',KeyK:'spin'}[e.code]);});window.addEventListener('keyup',e=>{if(e.code.startsWith('Shift'))boostHeld=false;});window.addEventListener('blur',()=>{boostHeld=false;if(state==='playing')togglePause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')togglePause();});for(let btn of document.querySelectorAll('[data-action]')){btn.addEventListener('pointerdown',e=>{e.preventDefault();btn.setPointerCapture(e.pointerId);if(btn.dataset.action==='boost')boostHeld=true;else act(btn.dataset.action);});for(let ev of ['pointerup','pointercancel','lostpointercapture'])btn.addEventListener(ev,()=>{if(btn.dataset.action==='boost')boostHeld=false;});}
function updateHUD(){ $('score').textContent=String(Math.floor(score)).padStart(5,'0');$('combo').textContent=combo>1?`落地连击 · ×${combo}`:'自由滑行 · ×1';$('coins').textContent=coins;$('distance').textContent=Math.floor(distance);$('hearts').textContent='♥ '.repeat(health)+'♡ '.repeat(3-health);$('energy').style.width=energy+'%';let conditions=[coins>=12,tricks>=5,distance>=800];conditions.forEach((done,i)=>{if(done&&!completed.has(i)){completed.add(i);score+=500;toast('夜行清单完成 · +500');beep(1000,.2);}let el=$('m'+(i+1));el.classList.toggle('done',done);el.textContent=(done?'✓ ':'○ ')+[`收集拉面 ${Math.min(coins,12)} / 12`,`空中特技 ${Math.min(tricks,5)} / 5`,`滑行距离 ${Math.min(Math.floor(distance),800)} / 800 m`][i];});$('missionCount').textContent=completed.size+' / 3';}
let last=performance.now();function animate(now){requestAnimationFrame(animate);let dt=Math.min((now-last)/1000,.033);last=now;time+=dt;
if(state==='playing'){let speed=14+Math.min(distance/180,9)+(boostHeld&&energy>0?9:0);if(boostHeld&&energy>0)energy=Math.max(0,energy-dt*30);else energy=Math.min(100,energy+dt*7);distance+=speed*dt;score+=speed*dt*.5;x=THREE.MathUtils.damp(x,lanes[lane],12,dt);let oldY=y;vy-=22*dt;y+=vy*dt;const onRoof=platforms.some(p=>distance>=p.start&&distance<=p.end);if(y<=0&&onRoof){if(jumps>0&&airPoints>0){score+=airPoints*combo;toast(`完美落地 +${airPoints*combo} · ×${combo}`);combo=Math.min(combo+1,8);airPoints=0;landings++;beep(350+combo*70,.08);}y=0;vy=0;jumps=0;airTricks.clear();}if(!onRoof&&y<-.15)hit(true);if(y<-7)hit(true);for(let r of ramps)if(!r.used&&Math.abs(r.d-distance)<1.1&&Math.abs(r.x-x)<1.15&&y<.5){r.used=true;jump();vy=10.3;toast('屋顶起飞！');}for(let ob of obstacles)if(!ob.hit&&Math.abs(ob.d-distance)<1.25&&Math.abs(ob.x-x)<1.3&&y<1.3){ob.hit=true;hit();}for(let item of items){if(!item.taken&&Math.abs(item.d-distance)<1.25&&Math.abs(item.x-x)<1.1&&Math.abs(item.base-(y+.9))<1.6){item.taken=true;item.mesh.visible=false;coins++;score+=50*combo;energy=Math.min(100,energy+8);beep(650+(coins%4)*90,.065);}}
invincible=Math.max(0,invincible-dt);if(distance>platforms[platforms.length-1].start-180)chunk(platforms.length);chunks.forEach((g,i)=>{g.visible=i*36-18>distance-70&&i*36-18<distance+180;});track.position.z=distance;city.position.z=distance%90;street.position.z=-80+distance%20;rider.position.set(x,y,0);rider.rotation.z=-(lanes[lane]-x)*.09;rider.rotation.y=Math.sin(time*3)*.025;body.rotation.x=-.08-(boostHeld?.15:0);rider.scale.setScalar(1);rider.visible=invincible<=0||Math.sin(time*30)>-.3;camera.position.lerp(new THREE.Vector3(x*.28+1.4,6.1+y*.22,10.3+(boostHeld?.8:0)),1-Math.exp(-dt*5));camera.lookAt(x*.3,.9+y*.15,-8);camera.fov=THREE.MathUtils.damp(camera.fov,boostHeld&&energy>0?57:48,4,dt);camera.updateProjectionMatrix();updateHUD();}
else if(state==='intro'){rider.scale.setScalar(1.65);rider.position.set(0,.03+Math.sin(time*1.8)*.035,0);rider.rotation.y=2.55;body.rotation.x=.02*Math.sin(time*2);camera.position.set(11.7,7.3,13.7);camera.lookAt(-4,.6,-7);track.position.z=0;}
if(state!=='paused'){tail.rotation.z=-.3+Math.sin(time*4)*.12;head.rotation.z=Math.sin(time*1.6)*.045;for(let it of items){if(Math.abs(it.d-distance)<110){it.mesh.rotation.y=time*1.2;it.mesh.position.y=it.base+Math.sin(time*3+it.d)*.1;}}if(flip>0){flip=Math.max(0,flip-dt*2.5);board.rotation.z=Math.sin((1-flip)*Math.PI*2)*Math.PI;}else board.rotation.z=0;if(spin>0){spin=Math.max(0,spin-dt*1.8);body.rotation.y=(1-spin)*Math.PI*2;}else body.rotation.y=0;}
if(notice>0){notice-=dt;if(notice<=0)$('trick').classList.remove('show');}renderer.render(scene,camera);}
requestAnimationFrame(animate);window.addEventListener('resize',()=>{renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();if(state==='playing')visible('touch',matchMedia('(pointer:coarse)').matches||innerWidth<760);});
window.gameDebug={snapshot:()=>({state,distance,score,coins,health,y,lane,energy,tricks,combo}),action:act,start:reset};
if(document.modelContext?.registerTool){for(const tool of [{name:'read_skate_run',description:'读取当前屋顶滑板游戏的分数、距离和状态。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>window.gameDebug.snapshot()},{name:'start_skate_run',description:'开始或重新开始一局屋顶滑板游戏。当前局进度会重置。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(input&&Object.keys(input).length)throw Error('No arguments expected');reset();return window.gameDebug.snapshot();}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}
